"""The format's generated files, from its one source (data_map/document.py): the JSON Schema a host can validate
against (format/map.schema.json) and the component's types (component/document.ts, by json-schema-to-typescript).
Rewrites them and fails when either was out of date; run by the git hooks and CI.

  python tools/build_format.py
"""

import json
import subprocess
import sys

from pydantic.json_schema import GenerateJsonSchema

from checks import ROOT, node_tool, utf8_console
from data_map.document import MapDocument

SCHEMA = ROOT / "format" / "map.schema.json"
TYPES = ROOT / "component" / "document.ts"
BANNER = "// Generated by tools/build_format.py from data_map/document.py: never edit by hand."


class UntitledFields(GenerateJsonSchema):
    """No title on each field (only on each class): the types then name each class once, not each field."""

    def field_title_should_be_set(self, schema) -> bool:  # noqa: ANN001 (pydantic-core's schema types)
        return False


def bare_refs(schema: dict) -> dict:
    """A reference beside a default becomes anyOf[reference], as an optional one already is: json-schema-to-
    typescript would otherwise read it as a new type (Status1 for Status)."""
    for definition in schema.get("$defs", {}).values():
        for name, field in definition.get("properties", {}).items():
            if "$ref" in field and len(field) > 1:
                definition["properties"][name] = {"anyOf": [{"$ref": field.pop("$ref")}], **field}
    return schema


def schema_text() -> str:
    generated = bare_refs(MapDocument.model_json_schema(schema_generator=UntitledFields))
    schema = {"$schema": "https://json-schema.org/draft/2020-12/schema", **generated}
    return json.dumps(schema, indent=2, ensure_ascii=False) + "\n"


def types_text(schema: str) -> str:
    """The TypeScript types of the schema, formatted like the rest of the component."""
    npx = node_tool("npx")
    options: dict = {"cwd": ROOT, "capture_output": True, "text": True, "encoding": "utf-8", "check": True}
    types = subprocess.run([npx, "--no-install", "json2ts", "--bannerComment", BANNER], input=schema, **options)
    prettier = [npx, "--no-install", "prettier", "--stdin-filepath", TYPES.relative_to(ROOT).as_posix()]
    return subprocess.run(prettier, input=types.stdout, **options).stdout


def main() -> int:
    schema = schema_text()
    stale = []
    for path, expected in ((SCHEMA, schema), (TYPES, types_text(schema))):
        if not path.exists() or path.read_text(encoding="utf-8") != expected:
            path.write_text(expected, encoding="utf-8", newline="\n")
            stale.append(path.relative_to(ROOT).as_posix())
    for path in stale:
        print(f"✗ {path} was out of date: regenerated, `git add` it and retry")
    if not stale:
        print("✓ the schema and the component's types match data_map/document.py")
    return 1 if stale else 0


if __name__ == "__main__":
    utf8_console()
    sys.exit(main())
